using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using OpenAlex.Data; using OpenAlex.Data.Models;
namespace OpenAlex.Web.Pages.Admin;
[Authorize(Policy="AdminPolicy")]
public sealed class EditUserRolesModel:PageModel{private readonly RoleManagementRepository _repository; public EditUserRolesModel(RoleManagementRepository repository)=>_repository=repository; [BindProperty(SupportsGet=true)] public long Id{get;set;} [BindProperty] public List<long> SelectedRoleIds{get;set;}=new(); [BindProperty] public string? ChangeReason{get;set;} public RoleManagementUser? UserProfile{get;private set;} public IReadOnlyList<RoleDefinition> Roles{get;private set;}=Array.Empty<RoleDefinition>(); public string? ErrorMessage{get;private set;} public async Task OnGetAsync(CancellationToken ct)=>await LoadAsync(ct); public async Task<IActionResult> OnPostAsync(CancellationToken ct){try{await _repository.SaveUserRolesAsync(Id,SelectedRoleIds,GetAdminName(),ChangeReason,ct); return RedirectToPage("/Admin/Roles");}catch(Exception ex){ErrorMessage=ex.Message; await LoadAsync(ct); return Page();}} async Task LoadAsync(CancellationToken ct){UserProfile=await _repository.GetUserAsync(Id,ct); Roles=await _repository.GetRolesAsync(ct); if(UserProfile is not null && SelectedRoleIds.Count==0){var lookup=Roles.ToDictionary(r=>r.RoleName,r=>r.AppRoleId,StringComparer.OrdinalIgnoreCase); SelectedRoleIds=UserProfile.Roles.Where(lookup.ContainsKey).Select(r=>lookup[r]).ToList();}} string GetAdminName()=>User?.Identity?.IsAuthenticated==true&&!string.IsNullOrWhiteSpace(User.Identity.Name)?User.Identity.Name!:"local.demo.admin";}
